P=dict(ch=9,nv=34,V=V,per=[17,17],out='/home/claude/work/gita/Gita_Chapter09.html',
 title='The Royal Secret · Bhagavad Gītā Chapter 9 · srini.presents',
 desc='Bhagavad Gītā chapter 9, Rāja Vidyā Rāja Guhya Yoga, every śloka explained: the royal secret, all beings in the Lord, “I carry their needs” (yoga-kṣemam vahāmy aham), a leaf, a flower, a fruit, water, offering everything, and “my devotee never perishes”. All 34 ślokas in IAST, each on two pages.',
 burst='CHAPTER 9 OF 18',h1='THE ROYAL SECRET',series='BHAGAVAD GĪTĀ · CHAPTER 9 · RĀJA VIDYĀ RĀJA GUHYA YOGA',tag='A leaf, a flower, a fruit · every śloka explained',cover=cover,
 where=[f'In {chl(8)} Kṛṣṇa taught that what we remember at death we become, and that the supreme abode is reached by undivided devotion.',
  'Chapter 9 is the most intimate chapter of devotion. Kṛṣṇa calls it the royal secret: easy, direct, and open to all. He pervades everything; he is father, mother and friend; he carries his devotees’ needs; he accepts a leaf or a flower offered with love; and his devotee never perishes.'],
 wtalk=("A whole chapter of promises?","Yes. Many call chapter 9 the heart of bhakti in the Gītā."),
 fullnote=FULLNOTE,
 secs=[('THE ROYAL SECRET',1),('ALL IN ME',4),('SCORN AND WORSHIP',11),('I AM ALL',16),('HEAVEN OR ME',20),('A LEAF, A FLOWER',26)],
 end=['<b>The secret (9.1–3).</b> The king of sciences: direct, righteous, easy, imperishable.',
  '<b>All in me (9.4–10).</b> He pervades all, untouched, like wind in space; nature creates under his gaze.',
  '<b>Two responses (9.11–15).</b> The deluded scorn his human form; great souls worship with one mind.',
  '<b>I am all (9.16–25).</b> The rite, the fire, father and mother, refuge and friend; heaven returns, but to his devotees he carries their needs.',
  '<b>A leaf, a flower (9.26–34).</b> Offer everything with love; he is the same to all; even the worst who turn are saved; my devotee never perishes.'],
 endsub='Chapter 9 in five lines',
 next=("What's next?",f'{chl(10)}: Divine glories. Arjuna asks where he should see the Lord, and Kṛṣṇa lists his splendours: among mountains Meru, among rivers Gaṅgā, among letters “a”.'),
 endkey='<b>offer anything with love; he carries the rest</b>.',
 foot=FOOT(9,'Stories of Vidura’s wife, Sudāmā and Vālmīki are traditional illustrations, not in the Gītā text. '))
build2(P)
